import{_ as e,a,b as r,c as o}from"./chunks/fs47-1.M5gSViS3.js";import{_ as n,a as l}from"./chunks/fs40-1.Bc5I7RCO.js";import{_ as s,a as i}from"./chunks/fs41-1.DENK6cZ8.js";import{_ as g,a as d}from"./chunks/fs50-1.CFxer_h3.js";import{_ as c,o as h,c as p,a4 as f}from"./chunks/framework.B0hSrcZ6.js";const k="/cases-img/fs42-0.png",u="/cases-img/fs42-1.jpg",y="/cases-img/fs43-0.png",m="/cases-img/fs43-1.jpg",b="/cases-img/fs46-0.jpg",x="/cases-img/fs46-1.png",P=JSON.parse('{"title":"英文长文精选（上）","description":"本页精选十一篇海外工程师的实操长文摘要，指导读者把控 Grok Bot 运行边界。涵盖中枢调度、团队规章、社媒运营与工程交付，提炼实战打法与配置避坑心得。","frontmatter":{},"headers":[],"relativePath":"cases/en1.md","filePath":"cases/en1.md","lastUpdated":1792210948000}'),B={name:"cases/en1.md"};function _(G,t,w,q,z,C){return h(),p("div",null,[...t[0]||(t[0]=[f(`<h1 id="英文长文精选-上" tabindex="-1">英文长文精选（上） <a class="header-anchor" href="#英文长文精选-上" aria-label="Permalink to &quot;英文长文精选（上）&quot;">​</a></h1><p>从单次对话走向全天候自主运行的云端智能体时，很多用户最常遇到的麻烦是把控不住边界。其具体问题主要体现在以下几个方面：</p><ul><li>有人把所有杂务塞给同一个 Bot，导致上下文迅速胀破，处理变慢的同时，容易在长对话中遗忘重要规则。</li><li>有人兴冲冲建了十几个 Bot，却因为缺乏统一调度入口，每天陷在不同会话窗口之间来回复制粘贴信息，沦为给 AI 跑腿的传话员。</li><li>还有些人急于让 Bot 接管外部账号，却忽略了单账号下共用一台云电脑的底层事实，误把角色名称当成安全隔离墙。</li></ul><p>这一章精选了海外工程师、一线业务负责人与独立创业者在 2026 年 8 月到 9 月期间沉淀的 11 篇深度实战长文。每篇摘要均以中文提炼出作者的真实打法、关键配置与避坑心得，帮你少走弯路，搭建稳定可靠的自动化工作流。</p><p>文选内容涵盖底层共享电脑机制解析、16 分钟系统化起步法则与单一幕僚长（Chief of Staff）调度中枢。此外还包含 21 项高阶极客技巧，以及 GTM 客户拓展、社媒全自动运营、多客户外包交付与工程值班实操。</p><p>阅读前可以先参考下表指引。你可以通过表格快速定位与当前业务最匹配的方向与核心机制：</p><table tabindex="0"><thead><tr><th style="text-align:left;">主题分类</th><th style="text-align:left;">文章标题</th><th style="text-align:left;">核心业务场景</th><th style="text-align:left;">关键机制与工具</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>机制理解与实操起步</strong></td><td style="text-align:left;">《Grok Bot Masterclass｜Avi Chawla》</td><td style="text-align:left;">底层共享电脑机制与技能例程固化</td><td style="text-align:left;">单机多屏、/workspace 共享、Teach a task 录屏、Auto Review 拦截</td></tr><tr><td style="text-align:left;"><strong>机制理解与实操起步</strong></td><td style="text-align:left;">《How to master Grok Bot in 16 minutes - Full Course｜CyrilXBT》</td><td style="text-align:left;">16 分钟系统化起步与分阶段进阶</td><td style="text-align:left;">单任务单 Bot 边界、循序渐进验证、Stripe 支付人闸</td></tr><tr><td style="text-align:left;"><strong>机制理解与实操起步</strong></td><td style="text-align:left;">《Grok Bot Agents: how to automate your life in 10 Steps (Full-tutorial)｜Codez》</td><td style="text-align:left;">从日常跑腿到专业 Agent 编队演进</td><td style="text-align:left;">岗位契约（Charter）、一分钟可逆性分权、无头自动化执行</td></tr><tr><td style="text-align:left;"><strong>中枢调度与团队规章</strong></td><td style="text-align:left;">《Grok Bot Chief of Staff: the charter, 10 rules and 5 routines I run｜kocer》</td><td style="text-align:left;">幕僚长单入口架构与 10 条底线守则</td><td style="text-align:left;">职责契约模板、10 条带测试用例家规、5 个核心例程</td></tr><tr><td style="text-align:left;"><strong>中枢调度与团队规章</strong></td><td style="text-align:left;">《From Zero to a Running Company: The Grok Bot Agent Team Playbook｜NO1ennn》</td><td style="text-align:left;">从零搭建一人全功能数字公司</td><td style="text-align:left;">部门级分工、全流程证据链要求、四周递进放权法则</td></tr><tr><td style="text-align:left;"><strong>中枢调度与团队规章</strong></td><td style="text-align:left;">《Every Grok Bot Hack I Know (Aug 2026)｜Matt Van Horn》</td><td style="text-align:left;">21 个高阶运维与提效黑客技巧</td><td style="text-align:left;">Compound Engineering、独立 AgentMail 邮箱、Tailscale Cookie 同步</td></tr><tr><td style="text-align:left;"><strong>市场拓展与社媒运营</strong></td><td style="text-align:left;">《Grok Bot for GTM｜Krista Letz》</td><td style="text-align:left;">SpaceXAI 内部 GTM 全流程销售作战</td><td style="text-align:left;">Granola 会议纪要联动 Figma、历史发件箱文风提取、意向信号研判</td></tr><tr><td style="text-align:left;"><strong>市场拓展与社媒运营</strong></td><td style="text-align:left;">《Grok Bot vs Hermes vs OpenClaw vs Buzz + How I fully automated my X content with Grok Bot｜SCOTTY BEAM》</td><td style="text-align:left;">主流 Agent 框架横评与 X 内容流水线</td><td style="text-align:left;">3 Bot 闭环生产、云端免运维、单 Bot 独立例程配置</td></tr><tr><td style="text-align:left;"><strong>一人公司与工程交付</strong></td><td style="text-align:left;">《How to Build an $18K/Month AI Agency on Grok (Exact Setup Inside)｜maestro》</td><td style="text-align:left;">基于双模型调用的自动化代运营机构</td><td style="text-align:left;">生产与审查物理解耦、19.5 万 Token 阈值拦截、3 次质检熔断</td></tr><tr><td style="text-align:left;"><strong>一人公司与工程交付</strong></td><td style="text-align:left;">《One-Computer Company: A Real Playbook For Running Solo On Grok Bot｜ZER》</td><td style="text-align:left;">独立开发者凭证管理与安全底线</td><td style="text-align:left;">单电脑凭证共享风险、凭证最小化录入、外发动作严格审批</td></tr><tr><td style="text-align:left;"><strong>一人公司与工程交付</strong></td><td style="text-align:left;">《Grok Bot for Engineering｜Lingxi Li》</td><td style="text-align:left;">SpaceXAI 官方工程团队 7×24 研运体系</td><td style="text-align:left;">5 研发 Bot + 1 运营 Bot、半小时 Notion 巡检、代码前后截图比对</td></tr></tbody></table><p>准备搭建业务流程时，可以把下面这段结构化提示词发给主 Bot。让它协助梳理岗位分工与执行目录：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我打算参考英文社区的实战经验，在 Grok Bot 中搭建一套自动化业务工作流：【填入具体业务场景，例如 GTM 客户拓展 / 自动化研发巡检 / 社媒内容生产】。</span></span>
<span class="line"><span>请帮我完成以下系统设计：</span></span>
<span class="line"><span>1. 岗位与中枢规划：设立统一的中枢调度 Bot（Chief of Staff）与专职角色，明确各角色的负责目标、输入源与交付物，严格遵循一人一岗原则。</span></span>
<span class="line"><span>2. 权限与人闸控制：按照操作可逆性划分权限，数据调研、草稿起草与归档分类由 Bot 自主执行，涉及外部发信、资金支付、配置修改与删除操作必须挂起等待人工确认。</span></span>
<span class="line"><span>3. 交付标准与证据链：为每个交付物制定验收标准，要求包含真实数据来源、时间戳或截图凭证，找不到数据直接报错，严禁猜测推断。</span></span>
<span class="line"><span>4. 运行稳定性设计：规划定时例程与静默规则，无新异常时保持静默不发无用通知，遇到连续执行失败时及时熔断并报警。</span></span></code></pre></div><h2 id="机制理解与实操起步" tabindex="-1">机制理解与实操起步 <a class="header-anchor" href="#机制理解与实操起步" aria-label="Permalink to &quot;机制理解与实操起步&quot;">​</a></h2><p>Grok Bot 自带持久化云电脑，能在后台独立执行。理清共享机制与权限边界，才能避开盲目建号与额度浪费。</p><h3 id="avi-chawla" tabindex="-1">Avi Chawla <a class="header-anchor" href="#avi-chawla" aria-label="Permalink to &quot;Avi Chawla&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/_avichawla/status/2089657097244024858" target="_blank" rel="noreferrer">Grok Bot Masterclass</a><br> 作者：<a href="https://x.com/_avichawla" target="_blank" rel="noreferrer">Avi Chawla @_avichawla</a></p></blockquote><p><img src="`+k+'" alt="Grok Bot Masterclass" decoding="async"></p><p><img src="'+u+'" alt="Grok Bot Masterclass" loading="lazy" decoding="async"></p><p>单账号下所有 Bot 共用云电脑的 <code>/workspace</code> 目录与浏览器会话，<strong>彼此没有安全隔离</strong>。全局设置里记得<strong>关掉本地电脑执行权限</strong>，把风险关在云端沙箱。</p><p>固化自动化操作分三步。</p><ol><li>用 Teach a task 录屏 10 分钟做成技能</li><li>升级为定时例程</li><li>遇到敏感认证切回人工接管</li></ol><p>审核规则按操作可逆性定，拦截审批保留一票否决权。</p><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/Qw17wVBhJibhkpkAK6zceiMvned" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="cyrilxbt" tabindex="-1">CyrilXBT <a class="header-anchor" href="#cyrilxbt" aria-label="Permalink to &quot;CyrilXBT&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/cyrilXBT/status/2094077928204083678" target="_blank" rel="noreferrer">How to master Grok Bot in 16 minutes - Full Course</a><br> 作者：<a href="https://x.com/cyrilXBT" target="_blank" rel="noreferrer">CyrilXBT @cyrilXBT</a></p></blockquote><p>别盲目多开 Bot 浪费额度。先建一个幕僚长 Bot 读项目历史摸清瓶颈，挑出 3 项最该自动化的任务。</p><p>平时<strong>坚决单任务单 Bot</strong>，防邮件和记账混在一起撑爆上下文。</p><p>自动化任务按四个阶段推进。</p><ol><li>人工跑通流程</li><li>单次触发验证</li><li>验证合格转定时 Routine</li><li>碰到 Stripe 扣款与密码登录，<strong>坚决交还人工</strong></li></ol><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/WGaCwZU71iHAGPkzjkLcahN2nHd" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="codez" tabindex="-1">Codez <a class="header-anchor" href="#codez" aria-label="Permalink to &quot;Codez&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/0xCodez/status/2089676836619878567" target="_blank" rel="noreferrer">Grok Bot Agents: how to automate your life in 10 Steps (Full-tutorial)</a><br> 作者：<a href="https://x.com/0xCodez" target="_blank" rel="noreferrer">Codez @0xCodez</a></p></blockquote><p><img src="'+y+'" alt="Grok Bot Agents: how to automate your life in 10 Steps (Full-tutorial)" loading="lazy" decoding="async"></p><p><img src="'+m+'" alt="Grok Bot Agents: how to automate your life in 10 Steps (Full-tutorial)" loading="lazy" decoding="async"></p><p>提示词按岗位契约（Charter）写成三段，定清负责领域、优良标准与禁止动作。浏览器里演示一遍录成技能，配日程或邮件触发器全天跑。</p><p>权限按一分钟可逆性划分：</p><table tabindex="0"><thead><tr><th style="text-align:left;">操作类型</th><th style="text-align:left;">业务动作</th><th style="text-align:left;">权限与执行策略</th></tr></thead><tbody><tr><td style="text-align:left;">完全可逆</td><td style="text-align:left;">归档、提炼与草稿</td><td style="text-align:left;">机器自主跑完</td></tr><tr><td style="text-align:left;">高风险/不可逆</td><td style="text-align:left;">对外发信与资金变动</td><td style="text-align:left;"><strong>必须等人工点击批准</strong></td></tr></tbody></table><p>每周固定复盘运行记录，<strong>坚决清理连续多周无产出的死例程</strong>。</p><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/PPKGwdkOkiGsxRkSInucbrNgnAg" target="_blank" rel="noreferrer">阅读原文</a></p><h2 id="中枢调度与团队规章" tabindex="-1">中枢调度与团队规章 <a class="header-anchor" href="#中枢调度与团队规章" aria-label="Permalink to &quot;中枢调度与团队规章&quot;">​</a></h2><p>Bot 多了容易抢指令或互相传错话。<strong>最稳的做法是用单一中枢 Bot 统一调度，定死规矩。</strong></p><h3 id="grok-bot-chief-of-staff-the-charter-10-rules-and-5-routines-i-run-kocer" tabindex="-1">Grok Bot Chief of Staff: the charter, 10 rules and 5 routines I run｜kocer <a class="header-anchor" href="#grok-bot-chief-of-staff-the-charter-10-rules-and-5-routines-i-run-kocer" aria-label="Permalink to &quot;Grok Bot Chief of Staff: the charter, 10 rules and 5 routines I run｜kocer&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/kocer_eth/status/2092216029816472002" target="_blank" rel="noreferrer">Grok Bot Chief of Staff: the charter, 10 rules and 5 routines I run</a><br> 作者：<a href="https://x.com/kocer_eth" target="_blank" rel="noreferrer">kocer @kocer_eth</a> 作者：kocer (@kocer_eth)</p></blockquote><p>担心角色越权或传话混乱，<strong>第一周只上线一个幕僚长 Bot 管全盘</strong>。配上职责契约与十条家规（每条附 30 秒实测用例），跑早间简报、周五复盘等 5 个固定例程。</p><ul><li>专业 Bot 必须全盘继承中枢权限红线，不得擅自放权。</li><li>交付结果必须附带事实来源，没有出处的数据一律留白。</li><li><strong>一旦输入 STOP ALL 立即全盘刹车。</strong></li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/BquAwgIC8iWFQlkPZFxc7uOsnSh" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="from-zero-to-a-running-company-the-grok-bot-agent-team-playbook-no1ennn" tabindex="-1">From Zero to a Running Company: The Grok Bot Agent Team Playbook｜NO1ennn <a class="header-anchor" href="#from-zero-to-a-running-company-the-grok-bot-agent-team-playbook-no1ennn" aria-label="Permalink to &quot;From Zero to a Running Company: The Grok Bot Agent Team Playbook｜NO1ennn&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/N01ennn/status/2091534159088959967" target="_blank" rel="noreferrer">From Zero to a Running Company: The Grok Bot Agent Team Playbook</a><br> 作者：<a href="https://x.com/N01ennn" target="_blank" rel="noreferrer">NO1ennn @N01ennn</a></p></blockquote><p><img src="'+e+'" alt="From Zero to a Running Company: The Grok Bot Agent Team Playbook" loading="lazy" decoding="async"></p><p><img src="'+a+'" alt="From Zero to a Running Company: The Grok Bot Agent Team Playbook" loading="lazy" decoding="async"> 作者：NO1ennn (@N01ennn)</p><p>一人团队可以用 1 个幕僚长加 4 至 6 名专员撑起公司。给团队下达整体业务目标，让 Bot 自行切分阶段并传递所有权。</p><p><strong>验收必须推行强证据链。</strong> 交付时必须提供操作录屏与数据出处，未核实的信息直接注明缺失。</p><p>自动化管理采取四周放权节奏。</p><ol><li>第一周逐字核查草稿。</li><li>第四周仅审验周度摘要。</li></ol><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/VGJmwyYrmiXLSSkdU3ackk1gnMd" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="every-grok-bot-hack-i-know-aug-2026-matt-van-horn" tabindex="-1">Every Grok Bot Hack I Know (Aug 2026)｜Matt Van Horn <a class="header-anchor" href="#every-grok-bot-hack-i-know-aug-2026-matt-van-horn" aria-label="Permalink to &quot;Every Grok Bot Hack I Know (Aug 2026)｜Matt Van Horn&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/mvanhorn/status/2092629365045559547" target="_blank" rel="noreferrer">Every Grok Bot Hack I Know (Aug 2026)</a><br> 作者：<a href="https://x.com/mvanhorn" target="_blank" rel="noreferrer">Matt Van Horn @mvanhorn</a></p></blockquote><p><img src="'+b+'" alt="Every Grok Bot Hack I Know (Aug 2026)" loading="lazy" decoding="async"></p><p><img src="'+x+'" alt="Every Grok Bot Hack I Know (Aug 2026)" loading="lazy" decoding="async"> 作者：Matt Van Horn (@mvanhorn)</p><p>管理 15 个 Bot 组成的矩阵时，复杂任务先出计划再施工。用专属邮箱隔离发信信誉，靠 Tailscale 保持会话 Cookie 持续同步。</p><ul><li>监控例程在无新情报时保持沉默，不产生通知噪音。</li><li>移动端直接发截屏交代任务，交由多模态能力自行提取日期与信息。</li><li><strong>任务拆解在 10 分钟录屏上限内，保证技能沉淀一次成型。</strong></li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/UGCCwisktiOC1Wk9adWcwN7env2" target="_blank" rel="noreferrer">阅读原文</a></p><h2 id="市场拓展与社媒运营" tabindex="-1">市场拓展与社媒运营 <a class="header-anchor" href="#市场拓展与社媒运营" aria-label="Permalink to &quot;市场拓展与社媒运营&quot;">​</a></h2><h3 id="grok-bot-for-gtm-krista-letz" tabindex="-1">Grok Bot for GTM｜Krista Letz <a class="header-anchor" href="#grok-bot-for-gtm-krista-letz" aria-label="Permalink to &quot;Grok Bot for GTM｜Krista Letz&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/kristaletz/status/2089103618121314689" target="_blank" rel="noreferrer">Grok Bot for GTM</a><br> 作者：<a href="https://x.com/kristaletz" target="_blank" rel="noreferrer">Krista Letz @kristaletz</a></p></blockquote><p><img src="'+n+'" alt="Grok Bot for GTM" loading="lazy" decoding="async"></p><p><img src="'+l+'" alt="Grok Bot for GTM" loading="lazy" decoding="async"></p><p>Krista Letz 在 SpaceXAI 用 Grok Bot 跑大客户销售。通话结束前几分钟，系统读取 Granola 会议纪要，自动在 Figma 幻灯片生成痛点总结页。</p><ul><li>扫描发件箱历史学个人文风，<strong>只生成待发草稿，不擅自触达</strong>。</li><li>挖意向时，<strong>强制关联 CRM 排除近九十天已联系的客户</strong>，杜绝撞车和机械骚扰。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/NcWow1eSZiJIu9kAcR0c4wHunKc" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="grok-bot-社媒全自动流水线-scotty-beam" tabindex="-1">Grok Bot 社媒全自动流水线｜SCOTTY BEAM <a class="header-anchor" href="#grok-bot-社媒全自动流水线-scotty-beam" aria-label="Permalink to &quot;Grok Bot 社媒全自动流水线｜SCOTTY BEAM&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/ScottyBeamIO/status/2089417013647073753" target="_blank" rel="noreferrer">Grok Bot vs Hermes vs OpenClaw vs Buzz + How I fully automated my X content with Grok Bot</a><br> 作者：<a href="https://x.com/ScottyBeamIO" target="_blank" rel="noreferrer">SCOTTY BEAM @ScottyBeamIO</a></p></blockquote><p><img src="'+s+'" alt="Grok Bot vs Hermes vs OpenClaw vs Buzz + How I fully automated my X content with Grok Bot" loading="lazy" decoding="async"></p><p><img src="'+i+'" alt="Grok Bot vs Hermes vs OpenClaw vs Buzz + How I fully automated my X content with Grok Bot" loading="lazy" decoding="async"></p><p>SCOTTY BEAM 用共享云电脑的文件系统流转物料，把搜趋势、按参考图生图和起草推文分给三个 Bot 协作。</p><table tabindex="0"><thead><tr><th style="text-align:left;">方案类型</th><th style="text-align:left;">代表产品</th><th style="text-align:left;">核心特征与运维成本</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>云端托管</strong></td><td style="text-align:left;">Grok Bot</td><td style="text-align:left;">免搭环境，维护省心</td></tr><tr><td style="text-align:left;"><strong>自托管</strong></td><td style="text-align:left;">Hermes、Buzz 等</td><td style="text-align:left;">需自行搭建与维护环境</td></tr></tbody></table><ul><li>团队群聊存不住定时例程，<strong>转在各个 Bot 的独立会话中单独配置触发调度</strong>。</li><li>顶层设巡查 Bot 统一生成每日执行汇总，<strong>推文最终发布权始终留在人工手里</strong>。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/RuhbwzhViiB3FwkYaylc8Uv7nLb" target="_blank" rel="noreferrer">阅读原文</a></p><h2 id="一人公司与工程交付" tabindex="-1">一人公司与工程交付 <a class="header-anchor" href="#一人公司与工程交付" aria-label="Permalink to &quot;一人公司与工程交付&quot;">​</a></h2><h3 id="maestro" tabindex="-1">maestro <a class="header-anchor" href="#maestro" aria-label="Permalink to &quot;maestro&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/maestrooth/status/2092658066714177657" target="_blank" rel="noreferrer">How to Build an $18K/Month AI Agency on Grok (Exact Setup Inside)</a><br> 作者：<a href="https://x.com/maestrooth" target="_blank" rel="noreferrer">maestro @maestrooth</a></p></blockquote><p><img src="'+r+'" alt="How to Build an $18K/Month AI Agency on Grok (Exact Setup Inside)" loading="lazy" decoding="async"></p><p><img src="'+o+'" alt="How to Build an $18K/Month AI Agency on Grok (Exact Setup Inside)" loading="lazy" decoding="async"></p><p>作者服务 5 家客户月入 1.8 万美元（未核）。<strong>路由层单次请求限 19.5 万 Token 以防计费翻倍</strong>。</p><ul><li>质检 Bot 仅设只读，按清单排查无出处数据与格式漏洞。</li><li><strong>质检失败 3 次强制熔断</strong>，转人工兜底。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/MtKDwMe0FiNf4wkxwj7cgnnAndf" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="zer" tabindex="-1">ZER <a class="header-anchor" href="#zer" aria-label="Permalink to &quot;ZER&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/zerqfer/status/2093299037705236540" target="_blank" rel="noreferrer">One-Computer Company: A Real Playbook For Running Solo On Grok Bot</a><br> 作者：<a href="https://x.com/zerqfer" target="_blank" rel="noreferrer">ZER @zerqfer</a></p></blockquote><p>多 Bot 共享云电脑会话，安全全看录入的凭证。</p><table tabindex="0"><thead><tr><th style="text-align:left;">事务类型</th><th style="text-align:left;">权限防线</th></tr></thead><tbody><tr><td style="text-align:left;">日常琐事</td><td style="text-align:left;">放权 Bot 处理</td></tr><tr><td style="text-align:left;">核心资产</td><td style="text-align:left;"><strong>坚决不录入云端</strong></td></tr><tr><td style="text-align:left;">外部支付</td><td style="text-align:left;"><strong>审批必须人工卡死</strong></td></tr></tbody></table><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/VcevwDlGGimAvjkEGGPceItanNg" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="lingxi-li" tabindex="-1">Lingxi Li <a class="header-anchor" href="#lingxi-li" aria-label="Permalink to &quot;Lingxi Li&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/lingxi/status/2094493172516966781" target="_blank" rel="noreferrer">Grok Bot for Engineering</a><br> 作者：<a href="https://x.com/lingxi" target="_blank" rel="noreferrer">Lingxi Li @lingxi</a></p></blockquote><p><img src="'+g+'" alt="Grok Bot for Engineering" loading="lazy" decoding="async"></p><p><img src="'+d+'" alt="Grok Bot for Engineering" loading="lazy" decoding="async"></p><p>团队月并超 2000 个 PR、管 200 多个并发 Agent。拆 5 名研发 Bot 和 1 名运营 Bot，每半小时拉 Notion 排障。</p><ul><li><strong>补丁交付必附前后对比截图，靠多模态核验变更</strong>。</li><li>运营 Bot 组织晨会复盘，凌晨定时跑代码清理。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/G2YNwaSvpixAhFkjL4xcVm0tn5d" target="_blank" rel="noreferrer">阅读原文</a></p>',95)])])}const M=c(B,[["render",_]]);export{P as __pageData,M as default};
